refentry.refsect1:
&reftitle.errors;


 Throws InvalidArgumentException if partition is out of range, and ValueError if topic contains null bytes.



 Throws RdKafka\Exception if librdkafka cannot return the queue, for example when the topic name is too long, or when called from a callback while RdKafka\KafkaConsumer::close is running.

  &reftitle.examples;

   RdKafka\KafkaConsumer::splitPartitionQueue example


<?php
$queues = [];

$conf->setRebalanceCb(function (RdKafka\KafkaConsumer $consumer, int $err, array $partitions) use (&$queues) {
    $cooperative = $consumer->getRebalanceProtocol() === 'COOPERATIVE';

    foreach ($partitions as $partition) {
        $key = $partition->getTopic() . ':' . $partition->getPartition();

        if ($err === RD_KAFKA_RESP_ERR__ASSIGN_PARTITIONS) {
            // Split before acknowledging the assignment
            $queues[$key] = $consumer->splitPartitionQueue($partition->getTopic(), $partition->getPartition());
        } else {
            unset($queues[$key]);
        }
    }

    if ($err === RD_KAFKA_RESP_ERR__ASSIGN_PARTITIONS) {
        $cooperative ? $consumer->incrementalAssign($partitions) : $consumer->assign($partitions);
    } else {
        $cooperative ? $consumer->incrementalUnassign($partitions) : $consumer->assign(null);
    }
});

$consumer = new RdKafka\KafkaConsumer($conf);
$consumer->subscribe(['orders']);

$handle = function (?RdKafka\Message $message): void {
    if ($message === null || $message->err === RD_KAFKA_RESP_ERR__PARTITION_EOF) {
        return;
    }

    if ($message->err !== RD_KAFKA_RESP_ERR_NO_ERROR) {
        throw new RuntimeException($message->errstr(), $message->err);
    }

    // Process $message->payload
};

while (true) {
    // Serves callbacks and any message that reached the consumer queue
    $handle($consumer->consume(10));

    foreach ($queues as $queue) {
        $handle($queue->consume(0));
    }
}
?>
